  ('0f20c1cd-8879-456a-8c78-6db09893ab01', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', null, 'topic'::public.curated_course_node_type, 'Supply Chain Strategy and End-to-End Value', 'Students begin by understanding the supply chain as a strategic system that links customers, products, suppliers, operations, logistics, information, money, and service outcomes.', 0),
