  ('0bb29d99-e8b1-4a85-8aa5-85f870f05e7f', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '8f373f0a-14b2-4188-9d11-10f5dcc13347', 'concept'::public.curated_course_node_type, 'Cost, responsiveness, flexibility, innovation, quality, and sustainability priorities', null, 0),
