  ('4d65da41-4111-47b7-9835-2922e6ad8a03', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'e45e2ac1-08cb-40d4-8f79-2f7a866593c7', 'concept'::public.curated_course_node_type, 'Quality at source and supplier quality links', null, 2),
