  ('1736080b-832e-4dc0-89e3-eb922625e39c', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '6b8cddab-ccd9-4e9c-b26c-cacf38df5583', 'concept'::public.curated_course_node_type, 'ERP configuration, controls, access, and implementation risk', null, 2),
  ('40b8e5f4-2889-4957-b975-ee962b0a8496', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '96d5a86f-fd73-4017-9e16-3f5cee038780', 'subtopic'::public.curated_course_node_type, 'Planning and execution systems', 'Different systems support planning, warehousing, transportation, sourcing, and visibility.', 1),
  ('ac88a279-45fd-421d-a7f8-00ea7a6491b7', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '40b8e5f4-2889-4957-b975-ee962b0a8496', 'concept'::public.curated_course_node_type, 'MRP, DRP, APS, WMS, TMS, SRM, OMS, and control towers', null, 0),
