  ('35de1abe-96ae-4e31-a474-9bad0dbefa49', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '7e9e9b49-e887-4017-afc2-e461c4b80063', 'concept'::public.curated_course_node_type, 'IoT, RFID, barcode, robotics, AI, digital twins, blockchain, and analytics platforms', null, 0),
  ('d5625937-a447-42ec-92a8-a7880e09e922', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '7e9e9b49-e887-4017-afc2-e461c4b80063', 'concept'::public.curated_course_node_type, 'Use cases for visibility, predictive maintenance, ETA, quality, traceability, and planning', null, 1),
  ('73e331d9-b21e-46e4-89fe-a0f8c1c8ee1e', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '7e9e9b49-e887-4017-afc2-e461c4b80063', 'concept'::public.curated_course_node_type, 'Cybersecurity, data governance, internal controls, and adoption barriers', null, 2),
