  ('d2cb9372-a200-4401-8f33-f6575d720dd5', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'fb2a043a-d949-4c6c-9fb3-05fd3b6813d2', 'concept'::public.curated_course_node_type, 'OTIF, fill rate, perfect order, lead time, inventory turns, forecast accuracy, and cash-to-cash', null, 0),
  ('7e2900e7-8510-4f8d-8937-9750817d8b9a', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'fb2a043a-d949-4c6c-9fb3-05fd3b6813d2', 'concept'::public.curated_course_node_type, 'Transportation cost, warehousing cost, procurement savings, quality, and supplier performance', null, 1),
  ('ce240a3f-7e73-433d-b63e-2d4efa795087', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'fb2a043a-d949-4c6c-9fb3-05fd3b6813d2', 'concept'::public.curated_course_node_type, 'Executive, functional, and operational metric layers', null, 2),
  ('b4ec8cf1-3a3c-4323-966a-dab3d4d88c75', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '929b0072-e72c-4c12-b4a6-b7665667d723', 'subtopic'::public.curated_course_node_type, 'Cost-service tradeoffs', 'Supply-chain decisions usually improve one dimension while worsening another. Students learn to quantify tradeoffs.', 1),
