  ('e4b8782a-09e9-400d-bcc4-68b9da9a602a', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', '929b0072-e72c-4c12-b4a6-b7665667d723', 'subtopic'::public.curated_course_node_type, 'Analytics for decisions', 'Analytics helps students move from reporting to better decisions.', 2),
  ('809ba70a-c073-4b11-9c8b-6dddfbcbc344', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'e4b8782a-09e9-400d-bcc4-68b9da9a602a', 'concept'::public.curated_course_node_type, 'Descriptive, diagnostic, predictive, prescriptive, and causal analytics', null, 0),
  ('81562320-e73d-40ca-8d4f-cfa8f46dbea2', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'e4b8782a-09e9-400d-bcc4-68b9da9a602a', 'concept'::public.curated_course_node_type, 'Scenario analysis, optimization basics, simulation intuition, and decision trees', null, 1),
  ('b3b201d2-7963-4583-8752-6d5cfb6d08cf', 'd2e3f4a5-6b7c-4d44-9e44-4f5a6b7c8d64', 'e4b8782a-09e9-400d-bcc4-68b9da9a602a', 'concept'::public.curated_course_node_type, 'Translating analysis into recommendations and implementation plans', null, 2),
